import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('beforeSession failure', () => {
  // spec: specs/hal-engine-config-hooks/spec.md#7
  it('calls onError with the original session and error before cleanup', async () => {
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const failure = new Error('setup failed');
    const calls: unknown[] = [];
    const provider: AIProvider = {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {
        beforeSession: async () => { throw failure; },
        onError: async (receivedSession, error) => { calls.push([receivedSession, error]); },
        afterSession: async () => { calls.push('afterSession'); },
      },
    });

    const result = await orchestrator.processMessage(session).catch((error: unknown) => error);
    expect({result, calls}).toEqual({result: failure, calls: [[session, failure], 'afterSession']});
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/beforeSessionError.test.ts"
